\begin{defn}
A sentence $!C$ \emph{separates} sets of sentences $\Gamma$ and
$\Delta$ if and only if $\Gamma \Entails !C$ and $\Delta \Entails
\lnot !C$. If no such !!{sentence} exists, then $\Gamma$ and $\Delta$
are \emph{inseparable}.
\end{defn}

