\begin{defn}
If $M$~is the $e$th Turing machine (in our fixed enumeration), we
say that $e$~is an \emph{index} of~$M$. We write $M_e$ for the $e$th
Turing machine.
\end{defn}

target.excerpt:
\begin{defn}
$M$ మన స్థిర లెక్కింపులో $e$వ ట్యూరింగ్ యంత్రం అయితే, $e$ను $M$ యొక్క
\emph{సూచిక} అంటాం. $e$వ ట్యూరింగ్ యంత్రాన్ని $M_e$ అని వ్రాస్తాం.
\end{defn}

source.excerpt:
\begin{thm}\ollabel{thm:universal-tm} There is a \emph{universal
  Turing machine}~$U$ which, when started on input $\tuple{e,n}$ 
  \begin{enumerate}
    \item halts iff $M_e$ halts on input~$n$, and
    \item if $M_e$ halts with output $m$, so does~$U$.
  \end{enumerate}
  $U$ thus computes the function $f\colon \Nat \times \Nat \pto \Nat$
  given by $f(e,n) = m$ if $M_e$ started on input~$n$ halts with
  output~$m$, and undefined otherwise.
\end{thm}

target.excerpt:
\begin{thm}\ollabel{thm:universal-tm} ఇన్‌పుట్ $\tuple{e,n}$పై ప్రారంభించినప్పుడు
  \begin{enumerate}
    \item $M_e$ ఇన్‌పుట్~$n$పై ఆగితే, అప్పుడే మాత్రమే ఆగే, మరియు
    \item $M_e$ అవుట్‌పుట్ $m$తో ఆగితే, తానూ అదే అవుట్‌పుట్‌తో ఆగే
  \end{enumerate}
  ఒక \emph{సార్వత్రిక ట్యూరింగ్ యంత్రం}~$U$ ఉంది. అందువల్ల $M_e$ను
  ఇన్‌పుట్~$n$పై ప్రారంభించినప్పుడు అవుట్‌పుట్~$m$తో ఆగితే
  $f(e,n) = m$గా, లేకపోతే నిర్వచితం కాకుండా ఉండే
  $f\colon \Nat \times \Nat \pto \Nat$ ప్రమేయాన్ని $U$ గణిస్తుంది.
\end{thm}

