\begin{thm}[Trakhtenbrot's Theorem]
  \ollabel{thm:trakhtenbrodt}
  It is undecidable if an arbitrary !!{sentence} of first-order logic has
  a finite model (i.e., is finitely satisfiable).
\end{thm}

