\begin{defn}
For each natural number~$n$, define the \emph{Church numeral}
$\num{n}$ to be the lambda term $\lambd[x][\lambd[y][(x(x(x(\dots
x(y)))))]]$, where there are $n$ $x$'s in all.
\end{defn}

