source.excerpt:
\begin{defn}[Compatibility of relation]
  A relation $R$ on terms is said to be \emph{compatible}
  if it satisfies following conditions:
  \begin{enumerate}
  \item If $R N N'$ then $R \lambd[x][N] \lambd[x][N']$
  \item If $R P P'$ then $R (PQ) (P'Q)$
  \item If $R Q Q'$ then $R (PQ) (PQ')$
  \end{enumerate}
\end{defn}

target.excerpt:
\begin{defn}[సంబంధపు అనుకూలత్వం]
  పదాలపై సంబంధం $R$ కింది షరతులను తీరుస్తే దానిని
  \emph{అనుకూలమైనది} అంటాం:
  \begin{enumerate}
  \item $R N N'$ అయితే $R \lambd[x][N] \lambd[x][N']$.
  \item $R P P'$ అయితే $R (PQ) (P'Q)$.
  \item $R Q Q'$ అయితే $R (PQ) (PQ')$.
  \end{enumerate}
\end{defn}

source.excerpt:
\begin{proof}
  By induction on the !!{derivation} of $P \aconvone Q$.
  \begin{enumerate}
  \item If the last rule is \olref{defn:aconvone4}, then $P$ is of the
    form $\lambd[x][N]$ and $Q$ of the form
    $\lambd[y][\Subst{N}{y}{x}]$, with $x \neq y$, $y \notin \FV{N}$
    and $\Subst{N}{y}{x}$ defined. We distinguish cases according to
    whether $x \in \FV{N}$:
    \begin{enumerate}
    \item If $x \in FV(N)$, then:
      \begin{align*}
        \FV{\lambd[y][\Subst{N}{y}{x}]} &=
        \FV{\Subst{N}{y}{x}} \setminus \{y\} \\
        & = ((\FV{N} \setminus \{x\}) \cup \{y\}) \setminus \{y\}
         && \text{ by \olref[sub]{thm:infv}} \\
        & = \FV{N} \setminus \{x\} \\
        & = \FV{\lambd[x][N]}
      \end{align*}
    \item If $x \notin FV(N)$, then:
      \begin{align*}
        \FV{\lambd[y][\Subst{N}{y}{x}]}
        & = FV{\Subst{N}{y}{x}} \setminus \{y\} \\
        & = \FV{N} \setminus \{x\}
         && \text{by \olref[sub]{thm:notinfv}} \\
        & = \FV{\lambd[x][N]}.
      \end{align*}
    \end{enumerate}
  \item The other three cases are left as exercises. 
  \end{enumerate}
\end{proof}

target.excerpt:
\begin{proof}
  $P \aconvone Q$ యొక్క \tetoken{వ్యుత్పత్తి}{!!{derivation}}
  నిర్మాణంపై ఆగమన పద్ధతిలో నిరూపిస్తాం.
  \begin{enumerate}
  \item చివరి నియమం \olref{defn:aconvone4} అయితే,
    $P$ రూపం $\lambd[x][N]$; $Q$ రూపం
    $\lambd[y][\Subst{N}{y}{x}]$. ఇక్కడ $x \neq y$,
    $y \notin \FV{N}$, $\Subst{N}{y}{x}$ నిర్వచితం.
    $x \in \FV{N}$ అవుతుందో లేదో బట్టి రెండు సందర్భాలు:
    \begin{enumerate}
    \item $x \in \FV{N}$ అయితే:
      \begin{align*}
        \FV{\lambd[y][\Subst{N}{y}{x}]} &=
        \FV{\Subst{N}{y}{x}} \setminus \{y\} \\
        & = ((\FV{N} \setminus \{x\}) \cup \{y\}) \setminus \{y\}
         && \text{\olref[sub]{thm:infv} ప్రకారం} \\
        & = \FV{N} \setminus \{x\} \\
        & = \FV{\lambd[x][N]}
      \end{align*}
    \item $x \notin \FV{N}$ అయితే:
      \begin{align*}
        \FV{\lambd[y][\Subst{N}{y}{x}]}
        & = \FV{\Subst{N}{y}{x}} \setminus \{y\} \\
        & = \FV{N} \setminus \{y\}
         && \text{\olref[sub]{thm:notinfv} ప్రకారం} \\
        & = \FV{N} \setminus \{x\}
         && \text{$x \notin \FV{N}$, $y \notin \FV{N}$ కనుక} \\
        & = \FV{\lambd[x][N]}.
      \end{align*}
      \sourcecorrection{OLTELAMALP-003}{మూలంలోని రెండు ఉపసందర్భాల్లో $FV(N)$, $FV\{\cdot\}$ అనే అసంపూర్ణ స్వేచ్ఛా-చర సంకేతాలు ఉన్నాయి. రెండవ సందర్భంలో ప్రతిస్థాపన సిద్ధాంతం నేరుగా $\FV{N}\setminus\{x\}$ను ఇవ్వదు; ముందుగా $\FV{N}\setminus\{y\}$ వస్తుంది. $x,y$ రెండూ $\FV{N}$లో లేవన్న కారణంతో అవసరమైన మధ్య దశను చేర్చాం.}
    \end{enumerate}
  \item మిగిలిన మూడు సందర్భాలను అభ్యాసాలుగా వదిలేస్తున్నాం.
  \end{enumerate}
\end{proof}

