       && \text{by inductive hypothesis} \\
      & = (\FV{P} \setminus \{x, y\}) \cup \FV{N}
       && x \notin \FV{N} \\
      & = (\FV{\lambd[y][P]} \setminus \{x\}) \cup \FV{N}
      \end{aligned}
      \end{multline*}

